import sys
from collections import defaultdict, deque

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

N, M, Q = read_ints()

# Read the graph
graph = defaultdict(list)
for _ in range(M):
    u, v = read_ints()
    graph[u].append(v)
    graph[v].append(u)

# Precompute distances using BFS
def bfs(start):
    dist = [-1] * (N + 1)
    queue = deque([start])
    dist[start] = 0
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return dist

# Precompute distances for all planets
distances = {}
for i in range(1, N + 1):
    distances[i] = bfs(i)

# Process queries
for _ in range(Q):
    a, b = read_ints()
